/// Textes legaux MyMHC integres a l'application (CGU + politique de
/// confidentialite). Source : documents officiels MHC (nov. 2026).
class LegalSection {
  const LegalSection({required this.heading, required this.paragraphs});

  final String? heading;
  final List<String> paragraphs;
}

class LegalDocument {
  const LegalDocument({
    required this.title,
    required this.subtitle,
    required this.sections,
  });

  final String title;
  final String subtitle;
  final List<LegalSection> sections;
}

const kCguDocument = LegalDocument(
    title: 'CONDITIONS GÉNÉRALES D\'UTILISATION',
    subtitle: 'Application MyMHC — Mobility Health Care',
    sections: [
      LegalSection(heading: null, paragraphs: ['Les présentes Conditions Générales d\'Utilisation (ci-après les « CGU ») régissent l\'accès et l\'utilisation de l\'application mobile et de la plateforme web MyMHC (ci-après l\'« Application »), éditée par Mobility Health Care S.A.S (ci-après « MHC »), société immatriculée sous le numéro RCCM CG-PNR-01-2026-B16-00012, dont le siège social est situé 8, rue Louniamou, Songolo, Pointe-Noire, République du Congo.', 'En cochant la case prévue à cet effet lors de la création d\'un compte, l\'Utilisateur reconnaît avoir pris connaissance des présentes CGU et les accepte sans réserve. Cette acceptation est une condition préalable et obligatoire à la création d\'un compte et à l\'utilisation de l\'Application. Les CGU relatives à la garantie d\'assurance elle-même figurent dans les Conditions Générales et Particulières de l\'Assureur partenaire, distinctes des présentes.']),
      LegalSection(heading: 'Article 1 — Définitions', paragraphs: ['Application ou MyMHC : l\'application mobile et la plateforme web éditées par MHC, permettant la souscription d\'une assurance voyage et le déclenchement d\'une assistance médicale.', 'Utilisateur : toute personne physique majeure créant et utilisant un compte sur l\'Application.', 'Compte : l\'espace personnel de l\'Utilisateur sur l\'Application, associé à ses identifiants de connexion.', 'Assuré principal : l\'Utilisateur titulaire du Compte, souscripteur ou bénéficiaire de la police d\'assurance.', 'Assuré additionnel : toute personne, notamment mineure, rattachée au Compte de l\'Assuré principal et couverte au titre de la même police, sans disposer de Compte propre.', 'Assureur partenaire : la compagnie d\'assurance auprès de laquelle la police est souscrite via l\'Application, et qui porte le risque garanti.', 'Partenaire-Santé : tout hôpital, clinique ou professionnel de santé membre du Réseau des Partenaires-Santé de MHC.', 'Contenu : toute donnée, information, document ou fichier généré, transmis ou consulté via l\'Application.']),
      LegalSection(heading: 'Article 2 — Objet de l\'Application', paragraphs: ['L\'Application permet à l\'Utilisateur de :', 'souscrire une police d\'assurance voyage auprès de l\'Assureur partenaire de son choix ;', 'consulter, gérer et télécharger les documents relatifs à sa police (Quittance, Attestation d\'Assistance Voyage, avenants) ;', 'déclencher une alerte SOS en cas d\'urgence médicale survenant pendant un voyage couvert ;', 'suivre l\'avancement de son dossier de prise en charge médicale ;', 'accéder aux coordonnées du Médecin-Conseil et du Partenaire-Santé compétent selon sa localisation.', 'L\'Application constitue un outil de coordination et de gestion mis à disposition par MHC. Elle ne se substitue ni à un avis médical, ni au contrat d\'assurance conclu avec l\'Assureur partenaire.']),
      LegalSection(heading: 'Article 3 — Accès à l\'Application et création de compte', paragraphs: ['La création d\'un Compte est réservée aux personnes physiques âgées de dix-huit (18) ans au moins, disposant de la pleine capacité juridique.', 'Les enfants mineurs ne peuvent pas créer de Compte propre. Ils sont ajoutés en tant qu\'Assuré additionnel au Compte d\'un Utilisateur majeur, sous la responsabilité de ce dernier.', 'L\'Utilisateur s\'engage à fournir des informations exactes, complètes et à jour lors de la création de son Compte et tout au long de son utilisation de l\'Application. Un seul Compte est autorisé par personne physique.', 'Les identifiants de connexion sont strictement personnels et confidentiels. L\'Utilisateur est seul responsable de leur conservation et de toute utilisation de son Compte, sauf en cas d\'usage frauduleux qu\'il aurait signalé à MHC dans les meilleurs délais.']),
      LegalSection(heading: 'Article 4 — Souscription et paiement', paragraphs: ['La souscription d\'une police d\'assurance et le paiement de la prime correspondante s\'effectuent directement depuis l\'Application, au moyen des interfaces de paiement (API) intégrées (carte bancaire, mobile money, ou tout autre moyen proposé).', 'MHC ne collecte ni ne conserve les données bancaires de l\'Utilisateur. Les transactions sont traitées par des prestataires de paiement tiers agréés, dans le respect des standards de sécurité applicables aux transactions électroniques.', 'Après validation du paiement, une Quittance est générée automatiquement, suivie de l\'Attestation d\'Assistance Voyage matérialisant la couverture souscrite. En cas d\'anomalie constatée sur la souscription (erreur, double paiement, incident technique), l\'Utilisateur peut solliciter une régularisation dans les conditions prévues par les documents contractuels applicables.']),
      LegalSection(heading: 'Article 5 — Déclenchement d\'une alerte SOS', paragraphs: ['La fonctionnalité d\'alerte SOS est accessible depuis l\'Application 24 heures sur 24 et 7 jours sur 7. Son déclenchement transmet automatiquement au Médecin-Conseil les informations du Compte de l\'Utilisateur nécessaires à l\'évaluation de sa situation.', 'L\'Utilisateur demeure responsable de l\'exactitude et de l\'actualité des informations renseignées dans son Compte, dont dépend la qualité de la prise en charge. En cas d\'urgence concernant un Assuré additionnel, l\'Utilisateur doit le préciser expressément lors du déclenchement de l\'alerte.']),
      LegalSection(heading: 'Article 6 — Obligations de l\'Utilisateur', paragraphs: ['L\'Utilisateur s\'engage à :', 'utiliser l\'Application conformément à sa destination et à la réglementation applicable ;', 'ne pas usurper l\'identité d\'un tiers, ni créer de Compte pour le compte d\'une autre personne majeure sans son autorisation ;', 'ne transmettre aucune fausse information, notamment médicale ;', 'maintenir à jour les informations de son Compte ;', 'ne pas tenter de contourner, altérer ou compromettre la sécurité de l\'Application.', 'Tout manquement à ces obligations peut entraîner la suspension ou la suppression du Compte dans les conditions de l\'Article 10, sans préjudice des conséquences prévues par les Conditions Générales d\'assurance applicables (notamment en cas de fausse déclaration).']),
      LegalSection(heading: 'Article 7 — Propriété intellectuelle', paragraphs: ['L\'Application, sa structure, ses fonctionnalités, ainsi que les marques, logos et contenus qui y figurent sont la propriété exclusive de MHC ou de ses partenaires, et sont protégés par la réglementation applicable en matière de propriété intellectuelle.', 'L\'Utilisateur bénéficie d\'un droit d\'usage personnel, non exclusif et non transférable de l\'Application, limité à la durée de son Compte et aux besoins liés à l\'utilisation des services proposés.']),
      LegalSection(heading: 'Article 8 — Protection des données personnelles', paragraphs: ['MHC collecte et traite les données personnelles de l\'Utilisateur, y compris certaines données de santé, dans la mesure nécessaire à la souscription, à la gestion de la police et à la coordination des prises en charge médicales.', 'Ces données sont traitées dans le respect de la réglementation applicable en matière de protection des données personnelles. L\'Utilisateur dispose d\'un droit d\'accès, de rectification et, dans les conditions prévues par la réglementation, de suppression de ses données, qu\'il peut exercer auprès de MHC selon les modalités précisées dans la politique de confidentialité de l\'Application.', 'Les modalités détaillées de collecte, de traitement et de conservation des données personnelles sont précisées dans la politique de confidentialité de l\'Application, qui complète les présentes CGU.']),
      LegalSection(heading: 'Article 9 — Disponibilité de l\'Application et responsabilité', paragraphs: ['MHC met en œuvre les moyens raisonnables pour assurer la disponibilité et le bon fonctionnement de l\'Application, sans garantir une disponibilité continue ou exempte d\'erreurs. L\'Application peut faire l\'objet d\'interruptions, notamment pour maintenance, mise à jour, ou en cas de force majeure.', 'La responsabilité de MHC au titre de l\'Application est limitée aux fonctionnalités techniques qu\'elle propose (souscription, alerte SOS, coordination des prises en charge). Elle ne saurait être étendue aux garanties d\'assurance elles-mêmes, dont la mise en œuvre relève de la seule responsabilité de l\'Assureur partenaire.']),
      LegalSection(heading: 'Article 10 — Suspension et suppression du compte', paragraphs: ['MHC peut suspendre ou supprimer un Compte, notamment en cas de manquement aux présentes CGU, de fraude avérée ou suspectée, ou d\'usage abusif de l\'Application, après en avoir informé l\'Utilisateur dans la mesure du possible.', 'L\'Utilisateur peut demander la suppression de son Compte à tout moment en contactant MHC. Cette suppression est sans effet sur les polices d\'assurance en cours, dont la gestion demeure régie par les documents contractuels applicables.']),
      LegalSection(heading: 'Article 11 — Modification des CGU', paragraphs: ['MHC peut modifier les présentes CGU à tout moment, notamment pour tenir compte d\'évolutions réglementaires ou fonctionnelles de l\'Application. L\'Utilisateur en est informé par tout moyen approprié avant leur entrée en vigueur. La poursuite de l\'utilisation de l\'Application après notification vaut acceptation des CGU modifiées.']),
      LegalSection(heading: 'Article 12 — Droit applicable et juridiction compétente', paragraphs: ['Les présentes CGU sont soumises au droit de la République du Congo. Tout litige relatif à leur validité, leur interprétation ou leur exécution relève de la compétence exclusive des juridictions du siège social de MHC, sauf disposition impérative contraire.']),
      LegalSection(heading: 'Article 13 — Contact', paragraphs: ['Pour toute question relative aux présentes CGU ou à l\'utilisation de l\'Application, l\'Utilisateur peut contacter MHC :', 'par e-mail : contact@mobilityhealth-care.com', 'par téléphone : +242 05 098 35 35', 'par courrier : Mobility Health Care S.A.S, 8, rue Louniamou, Songolo, Pointe-Noire, République du Congo']),
    ],
  );

const kPrivacyDocument = LegalDocument(
    title: 'POLITIQUE DE CONFIDENTIALITÉ',
    subtitle: 'Application MyMHC — Mobility Health Care',
    sections: [
      LegalSection(heading: null, paragraphs: ['La présente Politique de Confidentialité décrit la manière dont Mobility Health Care S.A.S (ci-après « MHC »), société immatriculée sous le numéro RCCM CG-PNR-01-2026-B16-00012, dont le siège social est situé 8, rue Louniamou, Songolo, Pointe-Noire, République du Congo, collecte, utilise, partage et protège les données personnelles des utilisateurs de l\'application MyMHC (ci-après l\'« Application »).', 'Elle complète les Conditions Générales d\'Utilisation de l\'Application et s\'applique à toute personne créant un compte ou utilisant l\'Application, ainsi qu\'aux Assurés additionnels dont les données sont renseignées par un Utilisateur titulaire d\'un compte.']),
      LegalSection(heading: 'Article 1 — Responsable du traitement', paragraphs: ['MHC est responsable du traitement des données personnelles collectées via l\'Application, au sens de la réglementation applicable en matière de protection des données.', 'Pour toute question relative au traitement de ses données, l\'Utilisateur peut contacter MHC aux coordonnées indiquées à l\'Article 12 de la présente Politique.']),
      LegalSection(heading: 'Article 2 — Données collectées', paragraphs: ['Selon l\'usage qui est fait de l\'Application, MHC est amenée à collecter les catégories de données suivantes :', 'données d\'identification : nom, prénom(s), date de naissance, sexe, nationalité, numéro de passeport ou de pièce d\'identité ;', 'données de contact : adresse e-mail, numéro de téléphone, pays de résidence ;', 'données relatives à l\'Assuré principal et aux Assurés additionnels rattachés à son Compte ;', 'données de santé : informations médicales transmises lors d\'une déclaration d\'urgence ou d\'un dossier de prise en charge, nécessaires à l\'évaluation et à la coordination de l\'assistance par le Médecin-Conseil ;', 'données de localisation : position géographique communiquée lors du déclenchement d\'une alerte SOS ;', 'données de paiement : MHC ne collecte ni ne conserve les données bancaires de l\'Utilisateur, celles-ci étant traitées directement par les prestataires de paiement tiers intégrés à l\'Application ;', 'données de connexion et d\'usage : identifiants de connexion, historique d\'utilisation de l\'Application, journaux techniques.']),
      LegalSection(heading: 'Article 3 — Finalités du traitement', paragraphs: ['Les données personnelles collectées sont utilisées aux fins suivantes :', 'permettre la création et la gestion du Compte de l\'Utilisateur ;', 'permettre la souscription d\'une police d\'assurance auprès de l\'Assureur partenaire et la génération des documents associés (Quittance, Attestation d\'Assistance Voyage, avenants) ;', 'permettre le déclenchement et le traitement d\'une alerte SOS, ainsi que la coordination de la prise en charge médicale par le Médecin-Conseil et le Partenaire-Santé ;', 'assurer la sécurité de l\'Application et prévenir toute utilisation frauduleuse ;', 'répondre aux obligations légales et réglementaires applicables à MHC ;', 'améliorer le fonctionnement et les services de l\'Application.']),
      LegalSection(heading: 'Article 4 — Base légale du traitement', paragraphs: ['Le traitement des données personnelles repose, selon les cas, sur l\'exécution du contrat liant l\'Utilisateur à MHC et à l\'Assureur partenaire, sur le consentement explicite de l\'Utilisateur pour le traitement de ses données de santé, sur le respect d\'obligations légales applicables à MHC, ou sur l\'intérêt légitime de MHC à assurer la sécurité et le bon fonctionnement de l\'Application.', 'Le consentement au traitement des données de santé est recueilli lors de la création du Compte et peut être retiré à tout moment, sans remettre en cause la licéité des traitements effectués avant ce retrait. Le retrait de ce consentement peut toutefois rendre impossible l\'utilisation de certaines fonctionnalités de l\'Application, notamment le déclenchement d\'une alerte SOS.']),
      LegalSection(heading: 'Article 5 — Destinataires des données', paragraphs: ['Les données personnelles de l\'Utilisateur peuvent être communiquées, dans la limite de ce qui est nécessaire à chaque finalité, aux destinataires suivants :', 'l\'Assureur partenaire, pour la gestion de la police d\'assurance ;', 'le Médecin-Conseil et le Partenaire-Santé compétent, pour l\'évaluation et la mise en œuvre de la prise en charge médicale ;', 'les prestataires de paiement tiers, pour le traitement des transactions ;', 'les prestataires techniques de MHC (hébergement, maintenance), agissant sur instruction de MHC et dans le respect de la présente Politique ;', 'les autorités compétentes, lorsque la loi l\'exige.', 'MHC ne vend ni ne loue les données personnelles des Utilisateurs à des tiers à des fins commerciales.']),
      LegalSection(heading: 'Article 6 — Durée de conservation', paragraphs: ['Les données personnelles sont conservées pendant la durée nécessaire à l\'utilisation du Compte, puis archivées pendant la durée requise par les obligations légales applicables ou par les délais de prescription en vigueur, avant d\'être supprimées ou anonymisées.', 'Les données de santé font l\'objet d\'une conservation limitée à la durée nécessaire à la gestion du dossier de prise en charge concerné, sauf obligation légale de conservation plus longue.']),
      LegalSection(heading: 'Article 7 — Sécurité des données', paragraphs: ['MHC met en œuvre les mesures techniques et organisationnelles raisonnables pour protéger les données personnelles contre l\'accès non autorisé, la perte, l\'altération ou la divulgation, notamment par le chiffrement des données sensibles, la restriction des accès aux seules personnes habilitées, et la sécurisation de ses infrastructures techniques.', 'Les données bancaires ne transitent à aucun moment par les serveurs de MHC ; elles sont traitées directement par les prestataires de paiement tiers, selon leurs propres standards de sécurité.']),
      LegalSection(heading: 'Article 8 — Droits de l\'Utilisateur', paragraphs: ['Conformément à la réglementation applicable, l\'Utilisateur dispose des droits suivants sur ses données personnelles :', 'droit d\'accès à ses données et aux informations relatives à leur traitement ;', 'droit de rectification des données inexactes ou incomplètes ;', 'droit à la suppression de ses données, dans les limites des obligations légales de conservation applicables à MHC ;', 'droit d\'opposition et de retrait du consentement, notamment pour le traitement des données de santé ;', 'droit à la portabilité de ses données, lorsque ce droit est applicable.', 'Ces droits peuvent être exercés en contactant MHC aux coordonnées indiquées à l\'Article 12. MHC peut demander toute information nécessaire à la vérification de l\'identité du demandeur avant de donner suite à sa demande.']),
      LegalSection(heading: 'Article 9 — Données des Assurés additionnels et des mineurs', paragraphs: ['Les données des Assurés additionnels, notamment des enfants mineurs rattachés au Compte d\'un Utilisateur majeur, sont renseignées et gérées sous la responsabilité de ce dernier, qui garantit disposer de l\'autorité nécessaire pour communiquer ces données à MHC.', 'MHC traite ces données selon les mêmes principes de protection que celles de l\'Assuré principal, dans la seule mesure nécessaire à la gestion de la police et à la coordination d\'une éventuelle prise en charge médicale.']),
      LegalSection(heading: 'Article 10 — Transferts de données', paragraphs: ['Dans la mesure où l\'exécution de certains traitements peut impliquer des prestataires situés dans un pays différent de celui de résidence de l\'Utilisateur, MHC veille à ce que ces transferts soient encadrés par des garanties appropriées, conformes à la réglementation applicable en matière de protection des données.']),
      LegalSection(heading: 'Article 11 — Modification de la Politique de Confidentialité', paragraphs: ['MHC peut modifier la présente Politique de Confidentialité à tout moment, notamment pour tenir compte d\'évolutions réglementaires ou fonctionnelles de l\'Application. L\'Utilisateur en est informé par tout moyen approprié avant l\'entrée en vigueur des modifications. La poursuite de l\'utilisation de l\'Application après notification vaut acceptation de la Politique modifiée.']),
      LegalSection(heading: 'Article 12 — Contact et réclamation', paragraphs: ['Pour toute question relative à la présente Politique ou pour exercer l\'un des droits mentionnés à l\'Article 8, l\'Utilisateur peut contacter MHC :', 'par e-mail : contact@mobilityhealth-care.com', 'par téléphone : +242 05 098 35 35', 'par courrier : Mobility Health Care S.A.S, 8, rue Louniamou, Songolo, Pointe-Noire, République du Congo', 'Si l\'Utilisateur estime que ses droits ne sont pas respectés, il peut également introduire une réclamation auprès de l\'autorité de protection des données compétente dans son pays de résidence, lorsqu\'une telle autorité existe.']),
    ],
  );
